#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <mma.h>
namespace {
using namespace nvcuda;
constexpr int IN_C = 3;
constexpr int OUT_C = 32;
constexpr int K = 3;
constexpr int K_ELEMS = IN_C * K * K;  // 27
constexpr int K_PAD = 32;             // reduction padded to multiple of 16
constexpr int NTILE = 256;            // output spatial positions per block
constexpr int THREADS = 256;
constexpr int WM = 16;
constexpr int WN = 16;
constexpr int WK = 16;
constexpr int SMEM_BYTES = OUT_C * NTILE * (int)sizeof(float);  // 32 KB
// Implicit-GEMM 3x3 convolution using bf16 tensor-core WMMA.
// GEMM view: C[oc][s] = sum_k W[oc][k] * im2col(X)[k][s],
//   M = 32 output channels, N = Ho*Wo spatial per image, K = 27 (padded to 32).
__global__ void conv3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo) {
  extern __shared__ __align__(16) unsigned char smem_raw[];
  __nv_bfloat16* sA = reinterpret_cast<__nv_bfloat16*>(smem_raw);  // [32][32]
  __nv_bfloat16* sB = reinterpret_cast<__nv_bfloat16*>(
      smem_raw + OUT_C * K_PAD * sizeof(__nv_bfloat16));           // [32][NTILE]
  float* sC = reinterpret_cast<float*>(smem_raw);                  // reused, [32][NTILE]
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int s0 = blockIdx.x * NTILE;
  const int S = Ho * Wo;
  // Stage weights [32][27] into padded [32][32] shared tile (matrix A).
  for (int idx = tid; idx < OUT_C * K_PAD; idx += THREADS) {
    const int oc = idx >> 5;
    const int k = idx & 31;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (k < K_ELEMS) {
      v = w[(size_t)oc * K_ELEMS + k];
    }
    sA[idx] = v;
  }
  // Stage im2col input tile [k][s] into shared memory (matrix B).
  // Thread tid owns spatial position s0+tid; coalesced along spatial dim.
  const int s = s0 + tid;
  const bool s_valid = (s < S);
  int oh = 0;
  int ow = 0;
  if (s_valid) {
    oh = s / Wo;
    ow = s - oh * Wo;
  }
  const __nv_bfloat16* xn = x + (size_t)n * IN_C * H * W;
  #pragma unroll
  for (int c = 0; c < IN_C; ++c) {
    #pragma unroll
    for (int ky = 0; ky < K; ++ky) {
      const int ih = oh + ky;
      #pragma unroll
      for (int kx = 0; kx < K; ++kx) {
        __nv_bfloat16 v = __float2bfloat16(0.0f);
        if (s_valid) {
          v = xn[((size_t)c * H + ih) * W + (ow + kx)];
        }
        sB[(c * 9 + ky * 3 + kx) * NTILE + tid] = v;
      }
    }
  }
  #pragma unroll
  for (int k = K_ELEMS; k < K_PAD; ++k) {
    sB[k * NTILE + tid] = __float2bfloat16(0.0f);
  }
  __syncthreads();
  // 8 warps: 2 rows of 16 output channels x 4 slabs of 64 spatial positions.
  const int warp = tid >> 5;
  const int warp_m = warp & 1;
  const int warp_n = warp >> 1;
  const int oc0 = warp_m * WM;
  const int sn0 = warp_n * 64;
  wmma::fragment<wmma::accumulator, WM, WN, WK, float> acc[4];
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    wmma::fill_fragment(acc[i], 0.0f);
  }
  #pragma unroll
  for (int kt = 0; kt < K_PAD / WK; ++kt) {
    wmma::fragment<wmma::matrix_a, WM, WN, WK, __nv_bfloat16, wmma::row_major> afrag;
    wmma::load_matrix_sync(afrag, sA + oc0 * K_PAD + kt * WK, K_PAD);
    #pragma unroll
    for (int nf = 0; nf < 4; ++nf) {
      wmma::fragment<wmma::matrix_b, WM, WN, WK, __nv_bfloat16, wmma::row_major> bfrag;
      wmma::load_matrix_sync(bfrag, sB + (kt * WK) * NTILE + sn0 + nf * WN, NTILE);
      wmma::mma_sync(acc[nf], afrag, bfrag, acc[nf]);
    }
  }
  __syncthreads();
  // Stage accumulators (f32) into shared memory, reusing the A/B buffer.
  #pragma unroll
  for (int nf = 0; nf < 4; ++nf) {
    wmma::store_matrix_sync(sC + oc0 * NTILE + sn0 + nf * WN, acc[nf], NTILE,
                            wmma::mem_row_major);
  }
  __syncthreads();
  // Convert to bf16 and write out. Each thread packs two adjacent spatial
  // positions into one 32-bit streaming store (st.global.cs): warp stores
  // are 128-byte coalesced and marked evict-first so the large output
  // tensor does not thrash the much smaller input tensor in L2, reducing
  // total DRAM traffic for this DRAM-bound kernel.
  {
    const int half = tid >> 7;            // 0 -> oc 0..15, 1 -> oc 16..31
    const int u = tid & 127;              // spatial pair index
    const int sp = s0 + 2 * u;            // first spatial position of the pair
    if (((S & 1) == 0) && (sp + 1 < S)) {
      // S even: every packed address is 4-byte aligned; all pairs full.
      __nv_bfloat16* yn = y + (size_t)n * OUT_C * S + sp;
      const float2* sCp = reinterpret_cast<const float2*>(sC + 2 * u);
      #pragma unroll 8
      for (int i = 0; i < 16; ++i) {
        const int oc = half * 16 + i;
