        const __nv_bfloat16 b0 = __float2bfloat16(f2.x);
        const __nv_bfloat16 b1 = __float2bfloat16(f2.y);
        const unsigned int packed =
            ((unsigned int)*reinterpret_cast<const unsigned short*>(&b1) << 16) |
            (unsigned int)*reinterpret_cast<const unsigned short*>(&b0);
        __stcs(reinterpret_cast<unsigned int*>(yn + (size_t)oc * S), packed);
      }
    } else if (sp < S) {
      // Odd-S fallback / ragged tail: scalar 16-bit streaming stores.
      __nv_bfloat16* yn = y + (size_t)n * OUT_C * S + sp;
      #pragma unroll 8
      for (int i = 0; i < 16; ++i) {
        const int oc = half * 16 + i;
        const __nv_bfloat16 b0 = __float2bfloat16(sC[oc * NTILE + 2 * u]);
        __stcs(reinterpret_cast<unsigned short*>(yn + (size_t)oc * S),
               *reinterpret_cast<const unsigned short*>(&b0));
        if (sp + 1 < S) {
          const __nv_bfloat16 b1 = __float2bfloat16(sC[oc * NTILE + 2 * u + 1]);
          __stcs(reinterpret_cast<unsigned short*>(yn + (size_t)oc * S + 1),
                 *reinterpret_cast<const unsigned short*>(&b1));
        }
      }
    }
  }
}
}  // namespace
torch::Tensor conv3x3_bf16(torch::Tensor x, torch::Tensor w) {
  TORCH_CHECK(x.is_cuda(), "input must be CUDA");
  TORCH_CHECK(w.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.dtype() == at::kBFloat16, "input must be bf16");
  TORCH_CHECK(w.dtype() == at::kBFloat16, "weight must be bf16");
  TORCH_CHECK(x.dim() == 4, "input must be NCHW");
  TORCH_CHECK(w.dim() == 4, "weight must be OIHW");
  TORCH_CHECK(x.size(1) == 3, "expected 3 input channels");
  TORCH_CHECK(w.size(0) == 32 && w.size(1) == 3 && w.size(2) == 3 && w.size(3) == 3,
              "expected weight shape [32, 3, 3, 3]");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  const int64_t N = x_c.size(0);
  const int64_t H = x_c.size(2);
  const int64_t W = x_c.size(3);
  TORCH_CHECK(H >= 3 && W >= 3, "spatial size must be >= 3");
  const int64_t Ho = H - 2;
  const int64_t Wo = W - 2;
